var sze = 20;
var num, bg;

function setup() {
	num =  floor(min(innerWidth, innerHeight) / sze)
	const minWH = num * sze;
	createCanvas(minWH, minWH);
	pixelDensity(1);
	frameRate(6);
	describe("transition of pixel blocks overlayed by animated figure");
}

function draw() {
	background(32);
	pasteSavedState();

	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed)) && mouseButton === LEFT /*&& frameCount % 4 === 0*/) drawBgLine();
	drawBgPattern();
	drawFgFigure();

	bg = get(0, 0, width, height)
}

function windowResized() {
	setup();
}

function pasteSavedState() {
	if (!bg) return;

	push()
	const ctx = drawingContext;
	ctx.beginPath();
	ctx.moveTo(0, height); // Move pen to bottom-left corner
	for (let x = 0, y = height; x < width; x += sze, y -= sze) {
		ctx.lineTo(x, y - sze); // Line to top corner
		ctx.lineTo(x + sze, y - sze); // Line to bottom-right corner
	}
	ctx.lineTo(width, height);

	ctx.closePath(); // Line to bottom-left corner
	ctx.clip();
	// tint(0, 153, 204);
	image(bg, sze, sze)
	pop()
}

function drawBgPattern() {
	// raster
	push();
	noStroke()
	fill("#dfe");
	const deviation = 5;
	const step = abs((frameCount % (deviation*2)) - deviation) + 2; // pendelum between 2..8..2
	for (let y = floor(step * 0.5); y < num; y += step) {
		for (let x = floor(step * 0.5); x < num; x += step) {
			if (x + y <= num) {
				rect(x * sze, y * sze, sze)
			}
		}
	}
	pop();
}
function drawBgLine() {
	// single line
	push();
	const xyOff = floor(num * 0.5) * sze;
	const yOff = sin(frameCount * 0.1)
	translate(xyOff, xyOff);
	// rotate(frameCount * 0.1);
	noStroke()
	fill("#fec");
	for (let x = - num; x < num; x++) {
		y = floor(x * yOff);
		rect(x * sze, y * sze, sze)
	}
	pop();
}

function drawFgFigure() {
	push();
	noStroke()
	fill(192, 32, 160); // fill(32, 192, 160);
	var minWH = max(width, height);
	const rad = sin(frameCount * 0.1) * minWH * 0.45;
	for (let a = 0; a < TWO_PI; a += TWO_PI / num * 1.5) {
		const cx = width * 0.5 + sin(a + a) * minWH * 0.1;
		const cy = height * 0.5 + cos(a + a) * minWH * 0.1;;
		const x = translateBlockCoord(cos(a) * rad + cx);
		const y = translateBlockCoord(sin(a) * rad + cy);
		rect(x, y, sze)
	}
	pop();
}

function translateBlockCoord(pos) {
	return sze * floor(pos / sze)
}
